// Builds database/hostinger_setup.sql: every migration plus its schema_migrations record, so the
// owner can set up the database with one phpMyAdmin import and `npm run db:migrate` later agrees.
// Run after adding a migration: node scripts/build-hostinger-sql.mjs
import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";

const dir = path.join(process.cwd(), "database", "migrations");
const files = fs.readdirSync(dir).filter(f => f.endsWith(".sql")).sort();
let out = `-- Idoconverter: one-file database setup for phpMyAdmin (Import tab).
-- Generated by scripts/build-hostinger-sql.mjs from database/migrations. Do not edit by hand.
-- Safe to import once into an EMPTY database. It records each migration so that
-- \`npm run db:migrate\` knows they are applied.

CREATE TABLE IF NOT EXISTS schema_migrations (
  version VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL PRIMARY KEY,
  checksum CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  applied_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
`;
for (const f of files) {
  const sql = fs.readFileSync(path.join(dir, f), "utf8");
  const sum = crypto.createHash("sha256").update(sql).digest("hex");
  const version = f.replace(/\.sql$/, "");
  out += `\n-- ===== ${f} =====\n${sql.trimEnd()}\n\nINSERT IGNORE INTO schema_migrations (version, checksum) VALUES ('${version}', '${sum}');\n`;
}
fs.writeFileSync(path.join(process.cwd(), "database", "hostinger_setup.sql"), out);
console.log(`Wrote database/hostinger_setup.sql (${files.length} migration${files.length === 1 ? "" : "s"})`);
